    /// <summary>
    /// Looks a key up by its generated member name. Avalonia's <c>PhysicalKey</c> enum uses the same
    /// W3C <c>code</c> names as Flutter's key constants, so the host adapter (and the test key
    /// simulator) bridge the two by name instead of carrying a second hand-maintained table.
    /// </summary>
    internal static PhysicalKeyboardKey? FindKeyByGeneratedName(string name) =>
        KeysByName.GetValueOrDefault(name);
}

